actions.script:
const out = ec.service.sync().name('org.moqui.comms.ChatScreenServices.get#ChatData').parameter('limit', limit ? Number(limit) : 200).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {me: out.me, prefs: out.prefs, roomList: out.roomList, unreadTotal: out.unreadTotal,
    mentionTotal: out.mentionTotal})

const out = ec.service.sync().name('org.moqui.comms.ChatScreenServices.find#ChatRooms').parameters({filter: filter || null, searchText: searchText || null,
    includeJoinable: String(includeJoinable) === 'true', joinableOnly: String(joinableOnly) === 'true', limit: limit ? Number(limit) : 200}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {roomList: out.roomList})

const number = (value) => value == null || value === '' ? null : Number(value)
const out = ec.service.sync().name('org.moqui.comms.ChatScreenServices.get#TimelinePage').parameters({chatRoomId: chatRoomId || '',
    beforeSeq: number(beforeSeq), afterSeq: number(afterSeq), aroundSeq: number(aroundSeq), threadRootEventSeq: number(threadRootEventSeq),
    pinnedOnly: String(pinnedOnly) === 'true', eventSeq: number(eventSeq), limit: number(limit) || 50}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : (out.page || {}))

const number = (value) => value == null || value === '' ? null : Number(value)
const out = ec.service.sync().name('org.moqui.impl.ChatServices.get#UserChanges').parameters({afterSeq: number(afterSeq),
    limit: number(limit) || 200, heads: String(heads) !== 'false', headsSince: number(headsSince)}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {changes: out.changeList || [], lastSeq: out.lastSeq, more: !!out.more,
    reset: !!out.reset, heads: out.headList ?? null, headsSince: out.headsSince ?? null})

const number = (value) => value == null || value === '' ? null : Number(value)
const out = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomChanges').parameters({chatRoomId: chatRoomId || '',
    afterSeq: number(afterSeq), limit: number(limit) || 200}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {changes: out.changeList || [], lastSeq: out.lastSeq, more: !!out.more,
    reset: !!out.reset})

const out = ec.service.sync().name('org.moqui.impl.ChatServices.find#RoomThreads').parameters({chatRoomId: chatRoomId || '',
    limit: limit ? Number(limit) : 20, beforeDate: beforeDate ? Number(beforeDate) : null, mine: String(mine) === 'true'}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {threadList: out.threadList, hasMore: out.hasMore})

const out = ec.service.sync().name('org.moqui.impl.ChatServices.find#Rooms').parameters({searchText: term || null, limit: 30}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? [] : Array.from(out.roomList || []).filter((room) => room.isMember && !room.archivedDate)
        .map((room) => ({value: room.chatRoomId, label: room.displayName})))

const out = ec.service.sync().name('org.moqui.impl.ChatServices.get#Attachment').parameter('chatAttachmentId', chatAttachmentId || '').call()
if (ec.message.hasError()) ec.web.sendJsonResponse({})
else ec.web.sendResourceResponse(out.location, String(inline) === 'true' && /^image\/(png|jpe?g|gif|webp)$/i.test(out.contentType || ''))

const out = ec.service.sync().name('org.moqui.comms.CommsServices.search#Users').parameters({term: term || '', limit: 12}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? [] : Array.from(out.userList || []).filter((user) => user.id !== ec.user.userId)
        .map((user) => ({value: user.id, label: user.label})))

const out = ec.service.sync().name('org.moqui.impl.ChatServices.search#ChatEvents').parameters({searchText: searchText || '',
    chatRoomId: chatRoomId || null, limit: 30}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {eventList: out.eventList, total: out.total})

const out = ec.service.sync().name('org.moqui.comms.ChatScreenServices.lookup#Records').parameters({operation: 'card',
    recordEntityName: recordEntity || '', recordId: recordId || ''}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : (out.card || {}))

const number = (value) => value == null || value === '' ? null : Number(value)
// an encrypted room's message (C7) is ciphertext: encryptedJson, with its mentions in the clear (mentionUserIds)
let sealed = null
try { sealed = encryptedJson ? JSON.parse(String(encryptedJson)) : null } catch (err) { sealed = {} }
const mentionList = mentionUserIds ? String(mentionUserIds).split(',').map((id) => id.trim()).filter((id) => id) : null
const out = ec.service.sync().name('org.moqui.comms.ChatScreenServices.send#ChatMessage').parameters({chatRoomId: chatRoomId || '', body: body || null,
    replyToEventSeq: number(replyToEventSeq), threadRootEventSeq: number(threadRootEventSeq), chatAttachmentIds: chatAttachmentIds || null,
    clientRef: clientRef || null, forwardOfChatRoomId: forwardOfChatRoomId || null, forwardOfEventSeq: number(forwardOfEventSeq),
    encrypted: sealed, mentionUserIdList: mentionList}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {reasonCode: out?.reasonCode || null} : {eventSeq: out.eventSeq, event: out.event, clientRef: out.clientRef, duplicate: out.duplicate})

// an encrypted room's message (C7) is ciphertext: encryptedJson, with its mentions in the clear (mentionUserIds)
let sealed = null
try { sealed = encryptedJson ? JSON.parse(String(encryptedJson)) : null } catch (err) { sealed = {} }
const mentionList = mentionUserIds ? String(mentionUserIds).split(',').map((id) => id.trim()).filter((id) => id) : null
const ran = ec.service.sync().name('org.moqui.impl.ClientSyncServices.call#ClientRequest').parameters({serviceName: 'org.moqui.impl.ChatServices.edit#Message',
    clientRef: clientRef || null, parameters: {chatRoomId: chatRoomId || '',
    eventSeq: Number(eventSeq || 0), body: body || null, encrypted: sealed, mentionUserIdList: mentionList, roomUrl: (System.getProperty('comms_app_root') || '/qapps/BasicComms') + '/Chat?chatRoomId=' + encodeURIComponent(chatRoomId || '')}}).call()
const out = (ran && ran.result) || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {editEventSeq: out.editEventSeq, event: out.event, duplicate: ran.duplicate === true})

const ran = ec.service.sync().name('org.moqui.impl.ClientSyncServices.call#ClientRequest').parameters({serviceName: 'org.moqui.impl.ChatServices.redact#Message',
    clientRef: clientRef || null, parameters: {chatRoomId: chatRoomId || '', eventSeq: Number(eventSeq || 0), reason: reason || null}}).call()
const out = (ran && ran.result) || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {redactionEventSeq: out.redactionEventSeq, duplicate: ran.duplicate === true})

// an encrypted room's reaction (C7): its key is ciphertext (encryptedJson), taken back by its reactionEventSeq
let sealed = null
try { sealed = encryptedJson ? JSON.parse(String(encryptedJson)) : null } catch (err) { sealed = {} }
const ran = ec.service.sync().name('org.moqui.impl.ClientSyncServices.call#ClientRequest').parameters({serviceName: 'org.moqui.impl.ChatServices.react#Message',
    clientRef: clientRef || null, parameters: {chatRoomId: chatRoomId || '', eventSeq: Number(eventSeq || 0), key: key || null, encrypted: sealed,
    reactionEventSeq: reactionEventSeq ? Number(reactionEventSeq) : null}}).call()
const out = (ran && ran.result) || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {added: out.added, reactionEventSeq: out.reactionEventSeq, duplicate: ran.duplicate === true})

const ids = optionIds ? String(optionIds).split(',').map((id) => id.trim()).filter((id) => id).map(Number) : []
const ran = ec.service.sync().name('org.moqui.impl.ClientSyncServices.call#ClientRequest').parameters({serviceName: 'org.moqui.impl.ChatServices.vote#Poll',
    clientRef: clientRef || null, parameters: {chatRoomId: chatRoomId || '', eventSeq: Number(eventSeq || 0), optionIdList: ids}}).call()
const out = (ran && ran.result) || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {poll: out.poll, duplicate: ran.duplicate === true})

const ran = ec.service.sync().name('org.moqui.impl.ClientSyncServices.call#ClientRequest').parameters({serviceName: 'org.moqui.impl.ChatServices.mark#Read',
    clientRef: clientRef || null, parameters: {chatRoomId: chatRoomId || '', eventSeq: eventSeq ? Number(eventSeq) : null,
    markUnread: String(markUnread) === 'true'}}).call()
const out = (ran && ran.result) || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {lastReadEventSeq: out.lastReadEventSeq, duplicate: ran.duplicate === true})

// the server has no text of an encrypted room's message (C7): nothing is made from it
// (only to one who may read the room: another learns nothing of it here, and gets the provider's "not found")
if (ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId || '').call()?.canRead
        && ec.entity.find('moqui.chat.ChatEvent').condition({chatRoomId: chatRoomId || '', eventSeq: Number(eventSeq || 0), encrypted: 'Y'}).count()) {
    ec.message.addError(ec.l10n.localize('An encrypted message is not read on the server: nothing is made from it')); ec.web.sendJsonResponse({reasonCode: 'encryptedRoom'}); return }
const out = ec.service.sync().name('org.moqui.impl.ShellServices.call#Providers').parameters({hook: 'create-from', mutation: true,
    parameters: {chatRoomId: chatRoomId || '', eventSeq: Number(eventSeq || 0), kind: kind || ''}}).call()
const made = (out?.results || [])[0] || {}
if (!ec.message.hasError() && out?.unavailable) ec.message.addError(ec.l10n.localize('Nothing here makes records from messages'))
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {recordEntityName: made.recordEntityName, recordId: made.recordId, url: made.url,
    roomRecordLinked: made.roomRecordLinked, messageInfos: [{type: 'success', message: made.message || ec.l10n.localize('Made'),
        link: made.url || null, linkText: ec.l10n.localize('Open')}]})

// the server has no text of an encrypted room's message (C7): it is not filed on a record
// (only to one who may read the room: another learns nothing of it here, and gets the provider's "not found")
if (ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId || '').call()?.canRead
        && ec.entity.find('moqui.chat.ChatEvent').condition({chatRoomId: chatRoomId || '', eventSeq: Number(eventSeq || 0), encrypted: 'Y'}).count()) {
    ec.message.addError(ec.l10n.localize('An encrypted message is not read on the server: it is not filed on a record')); ec.web.sendJsonResponse({reasonCode: 'encryptedRoom'}); return }
const out = ec.service.sync().name('org.moqui.impl.ShellServices.call#Providers').parameters({hook: 'record-link', mutation: true,
    parameters: {chatRoomId: chatRoomId || '', eventSeq: Number(eventSeq || 0), recordEntityName: recordEntityName || '',
        recordId: recordId || ''}}).call()
const filed = (out?.results || [])[0] || {}
if (!ec.message.hasError() && out?.unavailable) ec.message.addError(ec.l10n.localize('Nothing here files messages on records'))
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {communicationEventId: filed.communicationEventId, messageInfos: [{type: 'success',
    message: ec.l10n.localize('Filed on') + ' ' + (filed.title || ''), link: filed.url || null, linkText: ec.l10n.localize('Open')}]})

const out = ec.service.sync().name('org.moqui.comms.ChatScreenServices.create#ChatRoom').parameters({roomTypeEnumId: 'direct',
    memberUserIds: userIds || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {chatRoomId: out.chatRoomId, created: out.created})

const out = ec.service.sync().name('org.moqui.comms.ChatScreenServices.find#RecordRoom').parameters({recordEntityName: recordEntity || '',
    recordId: recordId || ''}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {chatRoomId: out.chatRoomId, created: out.created})

const ids = userIds ? String(userIds).split(',').map((id) => id.trim()).filter((id) => id) : []
const out = ec.service.sync().name('org.moqui.impl.ChatServices.add#Member').parameters({chatRoomId: chatRoomId || '', userIdList: ids}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {addedUserIdList: out.addedUserIdList})

if (!userId && !chatActorId) ec.message.addError(ec.l10n.localize('Who to take out?'))
else ec.service.sync().name('org.moqui.impl.ChatServices.remove#Member').parameters({chatRoomId: chatRoomId || '', userId: userId || null,
    chatActorId: userId ? null : chatActorId}).call()
ec.web.sendJsonResponse({})

const out = ec.service.sync().name('org.moqui.impl.CallServices.set#RoomCallEncryption').parameters({chatRoomId: chatRoomId || '',
    required: String(required) === 'true'}).requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({reasonCode: out.reasonCode || null, errors, required: !!out.required})

const out = ec.service.sync().name('org.moqui.impl.ChatKeyServices.set#RoomVerifiedDevicesOnly').parameters({chatRoomId: chatRoomId || '',
    verifiedDevicesOnly: String(verifiedDevicesOnly) === 'true'}).requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({reasonCode: out.reasonCode || null, errors, verifiedDevicesOnly: !!out.verifiedDevicesOnly})
